const PAGE_SLUG = PAGE_SLUGS.settingsControlPanel;
const MAX_PAIRING_WAIT_MS = 10 * 60_000;
const AUTHORIZATION_CODE_PAIRING_WAIT_MS = 25_000;
const MANUAL_RECOVERY_MESSAGE = "The latest one-time setup attempt has an ambiguous outcome. Do not retry or prepare a fresh connection; use the explicit manual recovery or offboarding process.";

export const getWhatsAppConfirmationTimeoutMessage = (
  diagnosticCode: WhatsAppEmbeddedSignupDiagnosticCode | null,
): string => {
  const prefix = "Meta did not return a usable WhatsApp Business account confirmation before the authorization expired.";
  switch (diagnosticCode) {
    case "rejected_event":
      return `${prefix} Meta sent a WhatsApp session event, but it was not a supported completion event.`;
    case "rejected_data":
      return `${prefix} Meta's completion event did not contain the expected account data.`;
    case "rejected_version":
      return `${prefix} Meta's completion event used an unsupported session version.`;
    case "rejected_waba":
      return `${prefix} Meta's completion event did not contain a valid business account reference.`;
    case "rejected_phone":
      return `${prefix} Meta's completion event contained an invalid phone reference.`;
    case "accepted":
      return `${prefix} A valid completion event was observed but could not be paired.`;
    default:
      return `${prefix} No trusted WhatsApp session event reached this page.`;
  }
};

export const getWhatsAppPairingWaitMs = (
  expiresAt: string,
  authorizationCodeReceived: boolean,
  now = Date.now(),
): number | null => {
  const remainingAttemptMs = new Date(expiresAt).getTime() - now;
  if (!Number.isFinite(remainingAttemptMs) || remainingAttemptMs <= 0) return null;
  const maximumWaitMs = authorizationCodeReceived
    ? AUTHORIZATION_CODE_PAIRING_WAIT_MS
    : MAX_PAIRING_WAIT_MS;
  return Math.min(remainingAttemptMs, maximumWaitMs);
};

type FlowStage =
  | "idle"
  | "preparing"
  | "ready"
  | "opening"
  | "waiting"
  | "submitting"
  | "complete"
  | "warning"
  | "error";

type OutboundStage = "idle" | "sending" | "accepted" | "error";

const extractErrorMessage = (error: unknown): string => {
  if (typeof error === "object" && error !== null) {
    const response = (error as { response?: { data?: unknown } }).response;
    const data = response?.data;
    if (typeof data === "string" && data.trim()) return data;
    if (Array.isArray(data) && data.length > 0) {
      const first = data[0];
      if (typeof first === "object" && first !== null && "message" in first) {
        const message = (first as { message?: unknown }).message;
        if (typeof message === "string" && message.trim()) return message;
      }
    }
    if (typeof data === "object" && data !== null && "message" in data) {
      const message = (data as { message?: unknown }).message;
      if (typeof message === "string" && message.trim()) return message;
    }
  }
  return error instanceof Error && error.message ? error.message : "Unexpected error occurred";
};

const statusColor = (status: string | null): string => {
  const value = (status ?? "").toLowerCase();
  if (["connected", "complete", "completed", "success", "succeeded", "requested"].includes(value)) return "teal";
  if (value === "declined") return "blue";
  if (["failed", "error", "unavailable", "disconnected"].includes(value)) return "red";
  if (["pending", "preparing", "provisioning", "in_progress", "in-progress", "syncing", "claimed", "unknown"].includes(value)) {
    return "yellow";
  }
  return "gray";
};

const displayStatus = (status: string | null): string =>
  status ? status.replace(/[_-]+/g, " ") : "Not started";

const maskMetaId = (value: string | null): string => {
  if (!value) return "Not configured";
  return value.length <= 6 ? "Configured" : `••••${value.slice(-6)}`;
};

const formatDateTime = (value: string | null): string => {
  if (!value) return "—";
  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? value : parsed.toLocaleString();
};

const syncRequestSucceeded = (status: string | null): boolean =>
  ["succeeded", "requested", "in_progress", "complete", "declined"].includes(status ?? "");

const completedWithoutWarnings = (status: WhatsAppAdminStatus): boolean =>
  status.connectionStatus === "connected"
  && status.tokenConfigured
  && status.wabaConfigured
  && status.phoneNumberConfigured
  && syncRequestSucceeded(status.appStateSyncStatus)
  && syncRequestSucceeded(status.historyDispatchStatus)
  && !status.recoveryRequired
  && !status.lastErrorCode;

const completionWasConfirmed = (status: WhatsAppAdminStatus, attemptId: string): boolean =>
  status.latestAttemptId === attemptId
  && status.connectionStatus === "connected"
  && ["complete", "completed"].includes((status.onboardingStatus ?? "").toLowerCase());

const freshAttemptIsSafe = (status: WhatsAppAdminStatus, attemptId: string): boolean =>
  status.latestAttemptId === attemptId
  && !status.recoveryRequired
  && ["failed", "expired"].includes((status.onboardingStatus ?? "").toLowerCase());

const SettingsWhatsApp = () => {
  const queryClient = useQueryClient();
  const statusQuery = useQuery<WhatsAppAdminStatus>({
    queryKey: WHATSAPP_ADMIN_STATUS_QUERY_KEY,
    queryFn: fetchWhatsAppAdminStatus,
  });
  const outboundTemplateQuery = useQuery<WhatsAppOutboundTemplate[]>({
    queryKey: WHATSAPP_OUTBOUND_TEMPLATES_QUERY_KEY,
    queryFn: fetchWhatsAppOutboundTemplates,
    enabled: Boolean(
      statusQuery.data?.connectionStatus === "connected"
      && statusQuery.data.coexistenceVerified
      && statusQuery.data.tokenConfigured
      && statusQuery.data.phoneNumberConfigured,
    ),
    staleTime: 60_000,
  });
  const [password, setPassword] = useState("");
  const [stage, setStage] = useState<FlowStage>("idle");
  const [feedback, setFeedback] = useState<string | null>(null);
  const [preparedExpiresAt, setPreparedExpiresAt] = useState<string | null>(null);
  const [reconnectAfterOffboarding, setReconnectAfterOffboarding] = useState(false);
  const [outboundRecipient, setOutboundRecipient] = useState("");
  const [outboundTemplateName, setOutboundTemplateName] = useState("");
  const [outboundLanguageCode, setOutboundLanguageCode] = useState("");
  const [outboundPassword, setOutboundPassword] = useState("");
  const [outboundStage, setOutboundStage] = useState<OutboundStage>("idle");
  const [outboundFeedback, setOutboundFeedback] = useState<string | null>(null);

  const attemptRef = useRef<WhatsAppEmbeddedSignupAttempt | null>(null);
  const sdkRef = useRef<MetaFacebookSdk | null>(null);
  const codeRef = useRef<string | null>(null);
  const sessionRef = useRef<WhatsAppEmbeddedSignupSession | null>(null);
  const sessionDiagnosticRef = useRef<WhatsAppEmbeddedSignupDiagnosticCode | null>(null);
  const completionStartedRef = useRef(false);
  const flowActiveRef = useRef(false);
  const pairingTimeoutRef = useRef<number | null>(null);
  const mountedRef = useRef(true);

  const clearPairingTimeout = useCallback(() => {
    if (pairingTimeoutRef.current !== null) {
      window.clearTimeout(pairingTimeoutRef.current);
      pairingTimeoutRef.current = null;
    }
  }, []);

  const clearSensitiveFlowData = useCallback((clearAttempt: boolean) => {
    clearPairingTimeout();
    codeRef.current = null;
    sessionRef.current = null;
    sessionDiagnosticRef.current = null;
    completionStartedRef.current = false;
    flowActiveRef.current = false;
    if (clearAttempt) {
      attemptRef.current = null;
      sdkRef.current = null;
      if (mountedRef.current) setPreparedExpiresAt(null);
    }
  }, [clearPairingTimeout]);

  const failFlow = useCallback((message: string) => {
    clearSensitiveFlowData(true);
    if (!mountedRef.current) return;
    setFeedback(message);
    setStage("error");
  }, [clearSensitiveFlowData]);

  const startPairingTimeout = useCallback(() => {
    if (pairingTimeoutRef.current !== null || completionStartedRef.current) return;
    const attempt = attemptRef.current;
    if (!attempt) {
      failFlow("Prepare a fresh connection before completing Meta signup.");
      return;
    }
    const authorizationCodeReceived = Boolean(codeRef.current);
    const pairingWaitMs = getWhatsAppPairingWaitMs(attempt.expiresAt, authorizationCodeReceived);
    if (pairingWaitMs === null) {
      failFlow("This secure connection attempt expired. Prepare a new one and try again.");
      return;
    }
    pairingTimeoutRef.current = window.setTimeout(() => {
      failFlow(authorizationCodeReceived
        ? getWhatsAppConfirmationTimeoutMessage(sessionDiagnosticRef.current)
        : "Meta did not return a usable authorization before the secure attempt expired. Prepare a new connection and try again.");
    }, pairingWaitMs);
  }, [failFlow]);

  const applyCompletionStatus = useCallback((status: WhatsAppAdminStatus) => {
    queryClient.setQueryData(WHATSAPP_ADMIN_STATUS_QUERY_KEY, status);
    if (!mountedRef.current) return;
    setReconnectAfterOffboarding(false);
    if (completedWithoutWarnings(status)) {
      setFeedback("WhatsApp Business is connected. App-state and history sync requests were submitted safely.");
      setStage("complete");
    } else {
      setFeedback("Connection details were saved, but the initial sync needs attention. Review the statuses above before retrying anything.");
      setStage("warning");
    }
  }, [queryClient]);

  const submitWhenReady = useCallback(() => {
    const attempt = attemptRef.current;
    const code = codeRef.current;
    const session = sessionRef.current;
    if (!attempt || !code || !session || completionStartedRef.current) return;

    completionStartedRef.current = true;
    flowActiveRef.current = false;
    clearPairingTimeout();
    if (mountedRef.current) {
      setFeedback("Securing the Meta connection and requesting the initial sync…");
      setStage("submitting");
    }

    // Keep the single-use authorization material in local scope only for this request.
    codeRef.current = null;
    sessionRef.current = null;
    attemptRef.current = null;
    sdkRef.current = null;
    setPreparedExpiresAt(null);

    void completeWhatsAppEmbeddedSignup(attempt.id, {
      nonce: attempt.nonce,
      code,
      session,
    })
      .then((status) => {
        applyCompletionStatus(status);
      })
      .catch(async () => {
        if (mountedRef.current) setReconnectAfterOffboarding(false);
        try {
          const status = await fetchWhatsAppAdminStatus();
          queryClient.setQueryData(WHATSAPP_ADMIN_STATUS_QUERY_KEY, status);
          if (completionWasConfirmed(status, attempt.id)) {
            applyCompletionStatus(status);
            return;
          }
          if (status.recoveryRequired) {
            if (!mountedRef.current) return;
            setFeedback(MANUAL_RECOVERY_MESSAGE);
            setStage("warning");
            return;
          }
          if (freshAttemptIsSafe(status, attempt.id)) {
            if (!mountedRef.current) return;
            setFeedback("The one-time code was discarded and the server marked this attempt as safely ended. Prepare a fresh secure connection to try again.");
            setStage("warning");
            return;
          }
        } catch {
          // The authorization code is one-use and has already been discarded; never replay it.
        }
        if (!mountedRef.current) return;
        setFeedback("The one-time code was discarded, but the final status could not be confirmed. Use Refresh status and do not retry until the status gives a safe next action.");
        setStage("warning");
      });
  }, [applyCompletionStatus, clearPairingTimeout, queryClient]);

  useEffect(() => {
    const handleMessage = (event: MessageEvent<unknown>) => {
      if (!flowActiveRef.current || completionStartedRef.current) return;
      const inspection = inspectWhatsAppEmbeddedSignupMessage(event);
      if (!inspection) return;
      sessionDiagnosticRef.current = inspection.diagnosticCode;
      const session = inspection.session;
      if (!session) return;
      sessionRef.current = session;
      startPairingTimeout();
      if (mountedRef.current) {
        setFeedback("Meta confirmed the WhatsApp Business account. Waiting for the secure authorization code…");
        setStage("waiting");
      }
      submitWhenReady();
    };

    window.addEventListener("message", handleMessage);
    return () => window.removeEventListener("message", handleMessage);
  }, [startPairingTimeout, submitWhenReady]);

  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
      clearPairingTimeout();
      codeRef.current = null;
      sessionRef.current = null;
      sessionDiagnosticRef.current = null;
      attemptRef.current = null;
      sdkRef.current = null;
      completionStartedRef.current = false;
      flowActiveRef.current = false;
    };
  }, [clearPairingTimeout]);

  useEffect(() => {
    const templates = outboundTemplateQuery.data ?? [];
    if (templates.length === 0) {
      setOutboundTemplateName("");
      setOutboundLanguageCode("");
      return;
    }
    const currentSelectionExists = templates.some((template) => (
      template.name === outboundTemplateName && template.language === outboundLanguageCode
    ));
    if (currentSelectionExists) return;
    const preferredTemplate = templates.find((template) => (
      template.name === "hello_world" && template.language === "en_US"
    )) ?? templates[0];
    setOutboundTemplateName(preferredTemplate.name);
    setOutboundLanguageCode(preferredTemplate.language);
  }, [outboundLanguageCode, outboundTemplateName, outboundTemplateQuery.data]);

  const handlePrepare = async () => {
    const passwordValue = password.trim();
    const isReconnectAttempt = reconnectAfterOffboarding;
    if (!passwordValue) {
      setFeedback("Enter your administrator password to prepare the connection.");
      setStage("error");
      return;
    }

    clearSensitiveFlowData(true);
    setPassword("");
    setFeedback(null);
    setStage("preparing");
    try {
      const attempt = await prepareWhatsAppEmbeddedSignup(passwordValue, isReconnectAttempt);
      if (new Date(attempt.expiresAt).getTime() <= Date.now()) {
        throw new Error("The connection attempt expired before it was ready. Please prepare a new one.");
      }
      const sdk = await loadMetaFacebookSdk({
        appId: attempt.launch.appId,
        graphApiVersion: attempt.launch.graphApiVersion,
      });
      if (!mountedRef.current) return;
      attemptRef.current = attempt;
      sdkRef.current = sdk;
      setPreparedExpiresAt(attempt.expiresAt);
      setFeedback(isReconnectAttempt
        ? "Ready. Continue with Meta to reconnect the offboarded WhatsApp Business number."
        : "Ready. Continue with Meta while this secure attempt is active.");
      setStage("ready");
    } catch (error) {
      failFlow(extractErrorMessage(error));
    }
  };

  const handleMetaLoginResponse = (response: MetaFacebookLoginResponse) => {
    if (!flowActiveRef.current || completionStartedRef.current) return;
    const code = response.authResponse?.code;
    if (typeof code !== "string" || code.length === 0 || code.length > 4096 || /\s/.test(code)) {
      failFlow("Meta sign-in was cancelled or did not return a usable authorization code.");
      return;
    }
    codeRef.current = code;
    startPairingTimeout();
    if (mountedRef.current) {
      setFeedback("Authorization received. Waiting for Meta to confirm the WhatsApp Business account…");
      setStage("waiting");
    }
    submitWhenReady();
  };

  const handleLaunch = () => {
    const attempt = attemptRef.current;
    const sdk = sdkRef.current;
    if (!attempt || !sdk) {
      failFlow("Prepare a fresh connection before opening Meta.");
      return;
    }
    if (new Date(attempt.expiresAt).getTime() <= Date.now()) {
      failFlow("This secure connection attempt expired. Prepare a new one and try again.");
      return;
    }

    codeRef.current = null;
    sessionRef.current = null;
    sessionDiagnosticRef.current = null;
    completionStartedRef.current = false;
    flowActiveRef.current = true;
    setFeedback("Complete the Meta flow and confirm the connection in your WhatsApp Business app.");
    setStage("opening");

    // This call must remain directly inside the click handler so browsers treat it as user-initiated.
    sdk.login(handleMetaLoginResponse, {
      config_id: attempt.launch.configId,
      response_type: "code",
      override_default_response_type: true,
      extras: {
        setup: {},
        featureType: META_WHATSAPP_SIGNUP_FEATURE,
        sessionInfoVersion: META_WHATSAPP_SESSION_INFO_VERSION_PARAMETER,
        version: META_WHATSAPP_EMBEDDED_SIGNUP_VERSION,
      },
    });
  };

  const handleReset = () => {
    clearSensitiveFlowData(true);
    setReconnectAfterOffboarding(false);
    setFeedback(null);
    setStage("idle");
  };

  const handleSendTemplateMessage = async () => {
    const recipient = normalizePhoneNumber(outboundRecipient);
    const templateName = outboundTemplateName.trim();
    const languageCode = outboundLanguageCode.trim();
    const passwordValue = outboundPassword;

    if (!isPhoneNumberValid(recipient) || !/^\+[1-9]\d{6,14}$/.test(recipient)) {
      setOutboundFeedback("Enter the recipient in international format, for example +48502484066.");
      setOutboundStage("error");
      return;
    }
    if (!/^[a-z0-9_]{1,512}$/.test(templateName)) {
      setOutboundFeedback("Enter a valid approved Meta template name.");
      setOutboundStage("error");
      return;
    }
    if (!/^[a-z]{2,3}(?:_[A-Z]{2})?$/.test(languageCode)) {
      setOutboundFeedback("Enter a valid template language code, for example en_US.");
      setOutboundStage("error");
      return;
    }
    if (!passwordValue.trim()) {
      setOutboundFeedback("Enter your administrator password to authorize this message.");
      setOutboundStage("error");
      return;
    }

    setOutboundRecipient(recipient);
    setOutboundPassword("");
    setOutboundFeedback(null);
    setOutboundStage("sending");
    try {
      await sendWhatsAppTemplateMessage({
        password: passwordValue,
        recipient,
        templateName,
        languageCode,
      });
      setOutboundFeedback("Meta accepted the WhatsApp message for delivery. This is not yet a delivery confirmation.");
      setOutboundStage("accepted");
    } catch (error) {
      setOutboundFeedback(extractErrorMessage(error));
      setOutboundStage("error");
    }
  };

  const status = statusQuery.data;
  const isBusy = ["preparing", "opening", "waiting", "submitting"].includes(stage);
  const canLaunch = stage === "ready" && Boolean(attemptRef.current && sdkRef.current);
  const outboundConfigured = Boolean(
    status?.connectionStatus === "connected"
    && status.coexistenceVerified
    && status.tokenConfigured
    && status.phoneNumberConfigured,
  );
  const outboundTemplateOptions = (outboundTemplateQuery.data ?? []).map((template) => ({
    value: `${template.name}|${template.language}`,
    label: `${template.name} (${template.language}, ${template.category.toLowerCase()})`,
  }));
  const selectedOutboundTemplate = outboundTemplateOptions.find(
    (template) => template.value === `${outboundTemplateName}|${outboundLanguageCode}`,
  )?.value ?? null;
  const flowAlertColor = stage === "complete"
    ? "teal"
    : stage === "warning"
      ? "yellow"
      : stage === "error"
        ? "red"
        : "blue";
  const flowAlertIcon = stage === "complete"
    ? <IconCheck size={18} />
    : stage === "error"
      ? <IconAlertCircle size={18} />
      : <IconClock size={18} />;
  const statusUpdatedLabel = useMemo(() => formatDateTime(status?.updatedAt ?? null), [status?.updatedAt]);

  return (
    <PageAccessGuard pageSlug={PAGE_SLUG}>
      <Stack gap="xl">
        <Group justify="space-between" align="flex-start" wrap="wrap">
          <Stack gap={4}>
            <Group gap="sm">
              <ThemeIcon color="teal" variant="light" size="lg">
                <IconBrandWhatsapp size={22} />
              </ThemeIcon>
              <Title order={3}>WhatsApp Business</Title>
            </Group>
            <Text size="sm" c="dimmed" maw={720}>
              Connect the existing WhatsApp Business app number to Meta Cloud API while continuing to use the mobile app.
              OmniLodge receives messages for the private morning brief and can send an approved Meta template when you
              explicitly authorize it below.
            </Text>
          </Stack>
          <Button
            variant="default"
            leftSection={<IconRefresh size={16} />}
            loading={statusQuery.isFetching}
            onClick={() => void statusQuery.refetch()}
          >
            Refresh status
          </Button>
        </Group>

        {statusQuery.isError ? (
          <Alert color="red" title="Unable to read WhatsApp status" icon={<IconAlertCircle size={18} />}>
            {extractErrorMessage(statusQuery.error)}
          </Alert>
        ) : null}

        <Card withBorder radius="md" padding="lg">
          <Stack gap="md">
            <Group justify="space-between" align="center" wrap="wrap">
              <Stack gap={2}>
                <Text fw={600}>Connection status</Text>
                <Text size="xs" c="dimmed">Last updated {statusUpdatedLabel}</Text>
              </Stack>
              <Badge color={statusColor(status?.connectionStatus ?? null)} variant="light" size="lg">
                {statusQuery.isLoading ? "Loading" : displayStatus(status?.connectionStatus ?? "unavailable")}
              </Badge>
            </Group>

            <SimpleGrid cols={{ base: 1, sm: 2, lg: 4 }} spacing="md">
              <Stack gap={3}>
                <Text size="xs" c="dimmed">Business token</Text>
                <Badge color={status?.tokenConfigured ? "teal" : "gray"} variant="dot">
                  {status?.tokenConfigured ? "Stored securely" : "Not configured"}
                </Badge>
              </Stack>
              <Stack gap={3}>
                <Text size="xs" c="dimmed">Meta launch configuration</Text>
                <Badge color={status?.launchConfigured ? "teal" : "gray"} variant="dot">
                  {status?.launchConfigured ? "Ready" : "Incomplete"}
                </Badge>
              </Stack>
              <Stack gap={3}>
                <Text size="xs" c="dimmed">Coexistence verification</Text>
                <Badge color={status?.coexistenceVerified ? "teal" : "gray"} variant="dot">
                  {status?.coexistenceVerified ? "Verified" : "Not verified"}
                </Badge>
              </Stack>
              <Stack gap={3}>
                <Text size="xs" c="dimmed">WABA ID</Text>
                <Text size="sm" fw={500}>{maskMetaId(status?.wabaId ?? null)}</Text>
              </Stack>
              <Stack gap={3}>
                <Text size="xs" c="dimmed">Phone number ID</Text>
                <Text size="sm" fw={500}>{maskMetaId(status?.phoneNumberId ?? null)}</Text>
              </Stack>
              <Stack gap={3}>
                <Text size="xs" c="dimmed">Onboarding</Text>
                <Badge color={statusColor(status?.onboardingStatus ?? null)} variant="light">
                  {displayStatus(status?.onboardingStatus ?? null)}
                </Badge>
              </Stack>
              <Stack gap={3}>
                <Text size="xs" c="dimmed">App-state sync</Text>
                <Badge color={statusColor(status?.appStateSyncStatus ?? null)} variant="light">
                  {displayStatus(status?.appStateSyncStatus ?? null)}
                </Badge>
              </Stack>
              <Stack gap={3}>
                <Text size="xs" c="dimmed">History sync progress</Text>
                <Badge color={statusColor(status?.historySyncStatus ?? null)} variant="light">
                  {displayStatus(status?.historySyncStatus ?? null)}
                </Badge>
              </Stack>
            </SimpleGrid>

            {status?.recoveryRequired ? (
              <Alert color="yellow" title="Manual recovery required" icon={<IconAlertCircle size={18} />}>
                {MANUAL_RECOVERY_MESSAGE}
              </Alert>
            ) : null}

            {status?.lastErrorCode ? (
              <Alert color="orange" title="Latest sanitized Meta error">
                {status.lastErrorCode}
              </Alert>
            ) : null}
          </Stack>
        </Card>

        <Card withBorder radius="md" padding="lg">
          <Stack gap="md">
            <Group gap="sm">
              <IconSend size={20} />
              <Title order={4}>Send a template message</Title>
            </Group>
            <Text size="sm" c="dimmed">
              This sends a real WhatsApp message immediately through the connected Meta Cloud API number. For a new
              conversation, use an approved template and only contact recipients who opted in. Meta acceptance does not
              guarantee delivery.
            </Text>
            {!outboundConfigured ? (
              <Alert color="yellow" title="WhatsApp connection required" icon={<IconAlertCircle size={18} />}>
                Complete and verify the WhatsApp Business connection before sending.
              </Alert>
            ) : null}
            {outboundConfigured && outboundTemplateQuery.isError ? (
              <Alert color="red" title="Unable to load approved templates" icon={<IconAlertCircle size={18} />}>
                {extractErrorMessage(outboundTemplateQuery.error)}
              </Alert>
            ) : null}
            {outboundConfigured
              && !outboundTemplateQuery.isLoading
              && !outboundTemplateQuery.isError
              && outboundTemplateOptions.length === 0 ? (
                <Alert color="yellow" title="No sendable template found" icon={<IconAlertCircle size={18} />}>
                  Create or approve a parameter-free message template in Meta before sending a new conversation.
                </Alert>
              ) : null}
            <SimpleGrid cols={{ base: 1, sm: 2 }} spacing="md">
              <TextInput
                label="Recipient phone (E.164)"
                placeholder="+48502484066"
                value={outboundRecipient}
                onChange={(event) => setOutboundRecipient(event.currentTarget.value)}
                disabled={outboundStage === "sending"}
              />
              <Select
                label="Approved parameter-free template"
                placeholder={outboundTemplateQuery.isLoading ? "Loading approved templates…" : "Select a template"}
                data={outboundTemplateOptions}
                value={selectedOutboundTemplate}
                onChange={(value) => {
                  const selected = (outboundTemplateQuery.data ?? []).find(
                    (template) => `${template.name}|${template.language}` === value,
                  );
                  setOutboundTemplateName(selected?.name ?? "");
                  setOutboundLanguageCode(selected?.language ?? "");
                }}
                disabled={!outboundConfigured || outboundTemplateQuery.isLoading || outboundStage === "sending"}
              />
              <PasswordInput
                label="Administrator password for sending"
                placeholder="Enter your current password"
                value={outboundPassword}
                onChange={(event) => setOutboundPassword(event.currentTarget.value)}
                autoComplete="current-password"
                disabled={outboundStage === "sending"}
              />
            </SimpleGrid>
            <Button
              color="teal"
              leftSection={<IconSend size={16} />}
              onClick={() => void handleSendTemplateMessage()}
              loading={outboundStage === "sending"}
              disabled={!outboundConfigured || !selectedOutboundTemplate || outboundStage === "sending"}
            >
              Send template message
            </Button>
            {outboundFeedback ? (
              <Alert
                color={outboundStage === "accepted" ? "teal" : "red"}
                title={outboundStage === "accepted" ? "Message accepted" : "Message not confirmed"}
                icon={outboundStage === "accepted" ? <IconCheck size={18} /> : <IconAlertCircle size={18} />}
              >
                {outboundFeedback}
              </Alert>
            ) : null}
          </Stack>
        </Card>

        <SimpleGrid cols={{ base: 1, lg: 2 }} spacing="lg">
          <Card withBorder radius="md" padding="lg">
            <Stack gap="md">
              <Group gap="sm">
                <IconShieldLock size={20} />
                <Title order={4}>1. Prepare a secure attempt</Title>
              </Group>
              <Text size="sm" c="dimmed">
                Re-enter your administrator password. The server creates a short-lived, single-use attempt and returns only
                safe Meta launch settings.
              </Text>
              <Checkbox
                label="I disconnected this number from Business Platform in the WhatsApp Business app"
                description="Select this only after offboarding the number in the mobile app. Leave it unchecked for a normal connection attempt."
                checked={reconnectAfterOffboarding}
                onChange={(event) => setReconnectAfterOffboarding(event.currentTarget.checked)}
                disabled={isBusy || stage === "ready"}
              />
              <PasswordInput
                label="Administrator password"
                placeholder="Enter your current password"
                value={password}
                onChange={(event) => setPassword(event.currentTarget.value)}
                autoComplete="current-password"
                disabled={isBusy || stage === "ready"}
              />
              <Button
                variant="light"
                leftSection={<IconShieldLock size={16} />}
                onClick={() => void handlePrepare()}
                loading={stage === "preparing"}
                disabled={isBusy || stage === "ready"}
              >
                {reconnectAfterOffboarding ? "Prepare re-onboarding" : "Prepare connection"}
              </Button>
            </Stack>
          </Card>

          <Card withBorder radius="md" padding="lg">
            <Stack gap="md">
              <Group gap="sm">
                <IconBrandFacebook size={20} />
                <Title order={4}>2. Continue with Meta</Title>
              </Group>
              <Text size="sm" c="dimmed">
                Meta opens its official Coexistence flow. Keep the phone with the WhatsApp Business app nearby to confirm the
                connection and approve history sync.
              </Text>
              {preparedExpiresAt ? (
                <Text size="xs" c="dimmed">Secure attempt expires {formatDateTime(preparedExpiresAt)}</Text>
              ) : null}
              <Button
                color="blue"
                leftSection={<IconBrandFacebook size={16} />}
                onClick={handleLaunch}
                disabled={!canLaunch}
              >
                {reconnectAfterOffboarding ? "Continue re-onboarding with Meta" : "Continue with Meta"}
              </Button>
              {stage === "opening" || stage === "waiting" ? (
                <Button variant="subtle" color="gray" onClick={handleReset}>
                  Cancel this attempt
                </Button>
              ) : null}
            </Stack>
          </Card>
        </SimpleGrid>

        {feedback ? (
          <Alert
            color={flowAlertColor}
            icon={flowAlertIcon}
            title={
              stage === "error"
                ? "Connection not completed"
                : stage === "warning"
                  ? "Initial sync needs attention"
                  : undefined
            }
          >
            {feedback}
          </Alert>
        ) : null}

        <Card withBorder radius="md" padding="lg">
          <Stack gap="sm">
            <Text fw={600}>Before you start</Text>
            <List size="sm" spacing="xs">
              <List.Item>Use the existing number from the WhatsApp Business app, not a personal WhatsApp number.</List.Item>
              <List.Item>Keep the mobile app current and complete Meta’s in-app confirmation.</List.Item>
              <List.Item>OmniLodge never receives or stores the short-lived Meta authorization code in browser storage.</List.Item>
              <List.Item>The phone number is already registered, so this flow does not register it again.</List.Item>
            </List>
          </Stack>
        </Card>
      </Stack>
    </PageAccessGuard>
  );
};

export default SettingsWhatsApp;
